export const ICON_STROKE_WIDTH = 2

type Props = SVGProps<SVGSVGElement> & { size?: number }
type IconNode = [string, Record<string, string | number>]

// Paint each dot in one fill, including the outer half of the rounded set's stroke.
function dot(cx: number, cy: number, radius: number): IconNode {
  return ['circle', { cx, cy, r: radius + ICON_STROKE_WIDTH / 2, fill: 'currentColor', stroke: 'none', key: `${cx}/${cy}` }]
}

function icon(name: string, nodes: IconNode[], strokeWidth = ICON_STROKE_WIDTH) {
  return function Icon({ size = 16, ...props }: Props) {
    return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" data-icon={name} {...props}>
      {nodes.map(([tag, attributes]) => createElement(tag, attributes))}
    </svg>
  }
}

